/* Navegação, material editorial e modelos didáticos. Sem conexão com contas ou carteiras. */
const AcademyMath = {
 backlog(arrivals,capacity,blocks){if(!Number.isInteger(arrivals)||!Number.isInteger(capacity)||!Number.isInteger(blocks)||arrivals<0||capacity<0||blocks<1||blocks>30)throw new RangeError('Use quantidades inteiras não negativas e entre 1 e 30 intervalos.');let pending=0;return Array.from({length:blocks},()=>{pending=Math.max(0,pending+arrivals-capacity);return pending;});},
 lending({quantity,price,debtUnits,debtPrice,apr,days,lt}) {
  const values=[quantity,price,debtUnits,debtPrice,apr,days,lt];
  if(values.some(v=>!Number.isFinite(v))||quantity<=0||price<=0||debtUnits<0||debtPrice<=0||apr<0||days<0||lt<=0||lt>100) throw new RangeError('Use valores positivos; dívida, prazo e juros podem ser zero. O limiar deve estar entre 0 e 100%.');
  const collateral=quantity*price,units=debtUnits*(1+apr/100*days/365),debt=units*debtPrice;
  if([collateral,units,debt].some(v=>!Number.isFinite(v)))throw new RangeError('Os valores excedem a precisão do simulador. Reduza a escala.');
  return {collateral,units,debt,hf:debt===0?Infinity:collateral*lt/100/debt,ltv:debt/collateral,liquidationPrice:debt/(quantity*lt/100)};
 },
 il(ratio){if(!Number.isFinite(ratio)||ratio<=0)throw new RangeError('A razão precisa ser positiva.');return 2*Math.sqrt(ratio)/(1+ratio)-1;},
 apy(apr,n){if(!Number.isFinite(apr)||!Number.isFinite(n)||apr<0||n<=0)throw new RangeError('Taxa e frequência inválidas.');return (1+apr/n)**n-1;},
 amm(x,y,input,fee){if([x,y,input,fee].some(v=>!Number.isFinite(v))||x<=0||y<=0||input<0||fee<0||fee>=1)throw new RangeError('Reservas positivas, entrada não negativa e taxa menor que 100%.');const effective=input*(1-fee);return {output:y*effective/(x+effective),newX:x+input,newY:y-y*effective/(x+effective)};}
};
const academy = {
 state:{version:1,completed:[],studied:[],scores:{},notes:{},bookmarks:[],last:'m1',level:1},chartSerial:0,stage:0,
 escape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));},
 module(id=app.currentView){return COURSE.find(m=>m.id===id);},
 announce(text){document.getElementById('announcement').textContent=text;},
 load(){
  try {const s=JSON.parse(localStorage.getItem('atlas-academy-v1'));if(s&&s.version===1){const ids=COURSE.map(m=>m.id);for(const k of ['completed','studied'])this.state[k]=Array.isArray(s[k])?[...new Set(s[k].filter(id=>ids.includes(id)))]:[];this.state.bookmarks=Array.isArray(s.bookmarks)?[...new Set(s.bookmarks.filter(k=>this.validBookmark(k)))]:[];for(const k of ['scores','notes'])this.state[k]=s[k]&&typeof s[k]==='object'&&!Array.isArray(s[k])?s[k]:{};this.state.last=ids.includes(s.last)?s.last:'m1';this.state.level=[1,2,3].includes(s.level)?s.level:1;}}
  catch(_){}
 },
 validBookmark(k){if(typeof k!=='string')return false;const c=k.indexOf(':');if(c>0){const m=this.module(k.slice(0,c));return !!m&&AcademyContent.isNew(m)&&m.lessons.some(l=>l.id===k.slice(c+1));}const h=k.indexOf('-');if(h<=0)return false;const m=this.module(k.slice(0,h)),i=k.slice(h+1);return !!m&&!AcademyContent.isNew(m)&&/^\d+$/.test(i)&&!!m.sections[Number(i)];},
 resolveBookmark(key){if(!this.validBookmark(key))return null;const c=key.indexOf(':');if(c>0){const m=this.module(key.slice(0,c)),l=m.lessons.find(x=>x.id===key.slice(c+1));return {m,title:l.title,ref:l.id};}const h=key.indexOf('-'),m=this.module(key.slice(0,h)),i=Number(key.slice(h+1));return {m,title:m.sections[i][0],ref:i};},
 count(m){return AcademyContent.isNew(m)?m.lessons.length:m.sections.length;},
 slug(s){return String(s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');},
 term(name){app.navigate('glossary');const el=document.getElementById('termo-'+this.slug(name));if(el){el.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'center'});el.tabIndex=-1;el.focus({preventScroll:true});}},
 save(){try{localStorage.setItem('atlas-academy-v1',JSON.stringify(this.state));return true;}catch(_){this.announce('O navegador não permitiu salvar. Os dados permanecem apenas nesta sessão.');return false;}},
 init(){
  this.load();
  const holder=document.createElement('div');holder.id='academy-templates';holder.hidden=true;
  Object.entries(ATLAS_TEMPLATES).forEach(([id,html])=>{const t=document.createElement('template');t.id='tpl-'+id;t.innerHTML=html;holder.append(t);});document.body.append(holder);
  this.updateNavigation();
  const legacySwitch=app.switchTab.bind(app);
  app.navigate=(id,tab='content',section=null,fromHash=false)=>{
   if(!['dashboard','sources','glossary','saved','search',...COURSE.map(m=>m.id)].includes(id))id='dashboard';
   this.destroyCharts();
   if(app.rafId){cancelAnimationFrame(app.rafId);app.rafId=null;}
   if(typeof web5!=='undefined'&&web5.txTimer){clearTimeout(web5.txTimer);web5.txTimer=null;}
   const oldRoute=location.hash;
   this.navigating=true;
   if(this.module(id)){
    const cont=document.getElementById('view-container');cont.replaceChildren(document.getElementById('tpl-'+id).content.cloneNode(true));app.currentView=id;app.chartsInit=false;this.state.last=id;this.save();this.enhance(this.module(id));this.initOriginalLabs(id);app.switchTab(['content','labs','infographics','assessment','sources'].includes(tab)?tab:'content');
   }else{app.currentView=id;document.getElementById('view-container').innerHTML=this[id==='dashboard'?'dashboard':id==='sources'?'sourceLibrary':id==='glossary'?'glossary':id==='saved'?'saved':'searchResults']();}
   this.navigating=false;
   this.updateNavigation();this.closeMenu();document.title='Atlas Academy — '+(this.module(id)?.title||({dashboard:'Visão geral',sources:'Fontes',glossary:'Glossário',saved:'Anotações',search:'Busca'}[id]));
   if(!fromHash){const validTab=['content','labs','infographics','assessment','sources'].includes(tab)?tab:'content';const route='#'+id+(this.module(id)?'/'+validTab:'');if(oldRoute!==route)history.pushState(null,'',route);}
   document.querySelector('main').scrollTop=0;
   if(window.matchMedia?.('(max-width:767px)').matches)window.scrollTo?.(0,0);
   const heading=document.querySelector('#view-container h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}
   this.icons();this.syncParent();this.announce((this.module(id)?.title||id)+' aberto.');if(section!==null)this.jump(id,section,false);
  };
  app.switchTab=(tabId,trigger)=>{
   if(!this.module())return;
   const button=trigger||document.querySelector('[data-tab="'+tabId+'"]');
   legacySwitch(tabId,button);
   document.querySelectorAll('.academy-tabs [role=tab]').forEach(b=>{const active=b.dataset.tab===tabId;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
   document.querySelectorAll('#view-container .tab-pane').forEach(p=>{p.hidden=p.id!=='tab-'+tabId;});
   if(tabId==='infographics')this.refreshVisuals();if(tabId==='labs')this.initExtraLabs();
   if(!this.navigating&&location.hash!=='#'+app.currentView+'/'+tabId)history.replaceState(null,'','#'+app.currentView+'/'+tabId);this.syncParent();this.fixLabLabels();
  };
  document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));document.getElementById('menu-toggle').setAttribute('aria-label',open?'Fechar menu':'Abrir menu');});
  document.addEventListener('click',e=>{if(!e.target.closest?.('.course-picker'))this.closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')this.closeMenu();if(e.target.matches?.('.academy-tabs [role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('.academy-tabs [role=tab]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();app.switchTab(tabs[i].dataset.tab,tabs[i]);}});
  document.getElementById('search-form').addEventListener('submit',e=>{e.preventDefault();this.query=document.getElementById('course-search').value.trim();app.navigate('search');});
  window.addEventListener('hashchange',()=>this.route());
  this.route();
 },
 route(){const [id,tab]=location.hash.slice(1).split('/');app.navigate(id||'dashboard',tab||'content',null,true);},
 icons(){if(window.lucide)lucide.createIcons();},
 closeMenu(){document.getElementById('sidebar').classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');document.getElementById('menu-toggle').setAttribute('aria-label','Abrir menu');},
 destroyCharts(){if(window.Chart&&Chart.instances)Object.values(Chart.instances).forEach(c=>c.destroy());if(typeof tokenLab!=='undefined'){tokenLab.distChart=null;tokenLab.chartsReady=false;}if(typeof defiCharts!=='undefined'){defiCharts.pool=null;defiCharts.il=null;defiCharts.ready=false;}if(typeof stableCharts!=='undefined'){stableCharts.depeg=null;stableCharts.ready=false;}if(typeof portLab!=='undefined'){portLab.donut=null;portLab.chart=null;}},
 updateNavigation(){const cur=this.module(app.currentView);document.getElementById('course-current-label').textContent=cur?String(COURSE.indexOf(cur)+1).padStart(2,'0')+' · '+cur.title:({sources:'Fontes',glossary:'Glossário',saved:'Anotações',search:'Busca'}[app.currentView]||'Visão geral');document.getElementById('module-navigation').innerHTML='<button class="nav-item '+(app.currentView==='dashboard'?'active':'')+'" onclick="app.navigate(\'dashboard\')"><i data-lucide="layout-dashboard" aria-hidden="true"></i>Visão geral</button>'+COURSE.map((m,i)=>`<button class="nav-item nav-${i+1} ${app.currentView===m.id?'active':''}" ${app.currentView===m.id?'aria-current="page"':''} onclick="app.navigate('${m.id}')"><i data-lucide="${m.icon}" aria-hidden="true"></i><span class="nav-title">${String(i+1).padStart(2,'0')} · ${m.title}</span>${this.state.completed.includes(m.id)?'<span class="nav-check" aria-label="Concluído">✓</span>':''}</button>`).join('');document.getElementById('sidebar-progress').textContent=this.state.completed.length+' de 10 módulos concluídos';document.getElementById('sidebar-meter').value=this.state.completed.length;this.icons();},
 /* Dentro do ATLAS o curso roda num iframe; a rota (#m6/labs) sobe para o
    endereço da página de fora, para recarregar e "continuar de onde parou"
    caírem no mesmo lugar. */
 syncParent(){try{if(window.parent!==window&&window.parent.location.pathname.indexOf('/academy/')!==-1){const p=window.parent.location,route=location.hash||'';if(p.hash!==route)window.parent.history.replaceState(null,'',p.pathname+p.search+route);}}catch(_){}},
 dashboard(){const total=COURSE.reduce((n,m)=>n+this.count(m),0);return `<section class="panel hero"><p class="eyebrow">ATLAS ACADEMY · TRILHA DE CRIPTOECONOMIA</p><h1>Conhecimento para entender.<br>Prática para conectar.</h1><p>Da primeira chave privada às estratégias de DeFi. Estude no seu ritmo, veja os mecanismos por dentro e consulte as fontes de cada assunto.</p><div class="actions"><button class="btn primary" onclick="app.navigate('${this.state.last}')">${Object.keys(this.state.scores).length||this.state.studied.length?'Continuar estudando':'Começar a trilha'} →</button><button class="btn" onclick="app.navigate('m2')">Explorar blockchain</button><button class="btn" onclick="app.navigate('m6')">Explorar DeFi</button></div></section><div class="stat-row"><div class="stat"><strong>${total}</strong><span>tópicos em 10 módulos</span></div><div class="stat"><strong>${Object.keys(SOURCES).length}</strong><span>fontes de referência</span></div><div class="stat"><strong>${this.state.completed.length}/10</strong><span>avaliações concluídas</span></div></div><section class="panel"><h2>Como cada módulo funciona</h2><p class="muted">Cada módulo começa pela história da ideia e segue em aulas curtas, com exemplos, figuras e fontes. Os assuntos mais difíceis ficam no fim, em "Indo além".</p><p class="reading-summary">A conclusão é registrada após acertar a avaliação inteira. Leitura, notas e favoritos são acompanhados separadamente neste navegador.</p></section><h2>Seu mapa de estudos</h2><div class="dashboard-grid">${COURSE.map((m,i)=>`<button class="module-card" onclick="app.navigate('${m.id}')"><span class="card-meta"><span>MÓDULO ${String(i+1).padStart(2,'0')}</span><span>${this.state.completed.includes(m.id)?'✓ Concluído':this.state.studied.includes(m.id)?'Leitura revisada':'Disponível'}</span></span><h3>${m.title}</h3><p>${m.summary}</p><span class="card-meta"><span>${this.count(m)} tópicos · ~${m.minutes} min</span><span>Explorar →</span></span></button>`).join('')}</div>${this.state.completed.length===10?'<section class="panel"><h2>Trilha concluída</h2><p>Você acertou as avaliações dos dez módulos. Continue revisitando fontes e cenários: protocolos e parâmetros podem mudar.</p><button class="btn" onclick="window.print()">Imprimir registro de estudo</button></section>':''}`;},
 enhance(m){
  const cont=document.getElementById('view-container'),wrap=cont.firstElementChild;
  const panes={};wrap.querySelectorAll('.tab-pane').forEach(p=>panes[p.id.replace('tab-','')]=p);
  const labs=panes.labs;const oldLab=labs?labs.innerHTML:'';
  wrap.innerHTML=`<header class="module-header"><p class="eyebrow">TRILHA DE ESTUDOS / MÓDULO ${m.id.slice(1).padStart(2,'0')}</p><h1>${m.title}</h1><p>${m.summary}</p><span class="pill">${this.count(m)} tópicos · ~${m.minutes} min de estudo</span><ul class="objective-list">${m.goals.map(g=>'<li>'+g+'</li>').join('')}</ul><p class="reading-summary">Fontes consultadas em 02/10/2026. Exemplos numéricos são didáticos; parâmetros reais variam por rede e mercado.</p></header><div class="academy-tabs" role="tablist" aria-label="Seções do módulo">${[['content','Aulas'],['labs','Laboratórios'],['infographics','Infográficos'],['assessment','Avaliação'],['sources','Fontes']].map(([id,label])=>`<button id="btn-${id}" class="tab-btn" data-tab="${id}" role="tab" aria-controls="tab-${id}" aria-selected="${id==='content'}" tabindex="${id==='content'?0:-1}" onclick="app.switchTab('${id}',this)">${label}</button>`).join('')}</div><section id="tab-content" class="tab-pane" role="tabpanel" aria-labelledby="btn-content">${this.lessons(m)}</section><section id="tab-labs" class="tab-pane hidden" role="tabpanel" aria-labelledby="btn-labs" hidden><div class="notice">Experimentos locais com valores fictícios. Eles não conectam sua carteira nem enviam transações. Modelos simplificam custos, liquidação e mercado.</div>${this.extraLabs(m)}<details class="panel legacy-labs"><summary>Laboratórios originais · explorar os mecanismos</summary><div class="notice warning">Hashes e assinaturas desta demonstração são representações didáticas, sem segurança criptográfica. Taxas, juros, retornos e séries de mercado são hipóteses ilustrativas. Não representam cotações ou garantias.</div><div class="legacy-content">${oldLab}</div></details></section><section id="tab-infographics" class="tab-pane hidden" role="tabpanel" aria-labelledby="btn-infographics" hidden>${AcademyRender.figures(m)}${this.visuals(m)}</section><section id="tab-assessment" class="tab-pane hidden" role="tabpanel" aria-labelledby="btn-assessment" hidden>${this.quiz(m)}</section><section id="tab-sources" class="tab-pane hidden" role="tabpanel" aria-labelledby="btn-sources" hidden>${this.moduleSources(m)}</section><footer class="module-footer"><button class="btn" onclick="app.navigate('${m.id==='m1'?'dashboard':'m'+(Number(m.id.slice(1))-1)}')">← ${m.id==='m1'?'Visão geral':'Módulo anterior'}</button><button class="btn" onclick="app.navigate('${m.id==='m10'?'dashboard':'m'+(Number(m.id.slice(1))+1)}')">${m.id==='m10'?'Visão geral':'Próximo módulo'} →</button></footer>`;
  this.bindLabSafety();this.fixLabLabels();
 },
lessons(m){const nw=AcademyContent.isNew(m),items=nw?[...m.lessons.filter(l=>!l.optional),...m.lessons.filter(l=>l.optional)].map(l=>({opt:!!l.optional,ref:l.id,title:l.title,html:null,l})):m.sections.map((s,i)=>({opt:s[1]===3,ref:i,title:s[0],s})).sort((a,b)=>Number(a.opt)-Number(b.opt));items.forEach((it,pos)=>{it.pos=pos;it.html=nw?AcademyRender.lesson(m,it.l,pos):this.oldLesson(m,it.s,it.ref,pos);});const first=items.findIndex(it=>it.opt),mainHtml=(first<0?items:items.slice(0,first)).map(it=>it.html).join(''),optItems=first<0?[]:items.slice(first),toc=(nw?`<a href="#${m.id}/content" onclick="event.preventDefault();academy.jump('${m.id}','historia')">Como tudo começou</a>`:'')+items.map((it,pos)=>(pos===first?`<a href="#${m.id}/content" onclick="event.preventDefault();academy.jump('${m.id}','alem')">Indo além (opcional)</a>`:'')+`<a href="#${m.id}/content" onclick="event.preventDefault();academy.jump('${m.id}',${JSON.stringify(it.ref).replace(/"/g,"'")})">${String(pos+1).padStart(2,'0')} · ${this.escape(it.title)}</a>`).join('');return `<div class="lesson-layout"><aside class="lesson-toc" aria-label="Índice das aulas"><h2>Neste módulo</h2>${toc}</aside><div>${nw?AcademyRender.history(m):''}${mainHtml}${optItems.length?`<section class="aula-alem"><h2 id="alem-${m.id}" tabindex="-1">Indo além (opcional)</h2><p class="muted">Assuntos mais difíceis. Você pode pular esta parte e voltar depois.</p>${optItems.map(it=>it.html).join('')}</section>`:''}<section class="note-box"><label for="module-notes">Suas palavras, seus exemplos</label><p class="muted">Use este espaço para preparar sua explicação do assunto.</p><textarea id="module-notes" placeholder="O que aprendi? Como eu explicaria isso?" oninput="academy.note(this.value)">${this.escape(this.state.notes[m.id]||'')}</textarea><small id="note-status">Notas salvas apenas neste navegador.</small></section><div class="actions" style="margin-top:20px"><button class="btn" onclick="academy.markStudied()">${this.state.studied.includes(m.id)?'✓ Leitura revisada':'Marcar leitura como revisada'}</button><button class="btn primary" onclick="app.switchTab('assessment')">Revisar com a avaliação →</button></div></div></div>`;},
 oldLesson(m,s,i,pos){const key=m.id+'-'+i;return `<article id="lesson-${key}" class="lesson"><h2>${String(pos+1).padStart(2,'0')}. ${s[0]}</h2><p class="explanation">${s[2]}</p><div class="example"><strong>Exemplo para conectar</strong>${s[3]}</div><div class="lesson-foot"><div class="source-inline">${s[4].map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener noreferrer">${SOURCES[k][0]} ↗</a>`).join('')}</div><button class="btn small" aria-pressed="${this.state.bookmarks.includes(key)}" onclick="academy.bookmark('${key}',this)">${this.state.bookmarks.includes(key)?'★ Salvo':'☆ Salvar'}</button></div></article>`;},
jump(id,i,navigate=true){const m=this.module(id);if(!m)return;const nw=AcademyContent.isNew(m);let elId;if(i==='alem'){if(!(nw?m.lessons.some(l=>l.optional):m.sections.some(x=>x[1]===3)))return;elId='alem-'+id;}else if(nw){if(i==='historia')elId='historia-'+id;else if(m.lessons.some(l=>l.id===i))elId='lesson-'+id+'-'+i;else return;}else{if(!m.sections[i])return;elId='lesson-'+id+'-'+i;}if(navigate&&app.currentView!==id)app.navigate(id);app.switchTab('content');const el=document.getElementById(elId);el?.scrollIntoView?.({behavior:window.matchMedia?.('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});const h=el?.matches?.('h2')?el:el?.querySelector('h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}},
 bookmark(key,button){const found=this.state.bookmarks.includes(key);this.state.bookmarks=found?this.state.bookmarks.filter(k=>k!==key):[...this.state.bookmarks,key];this.save();button.textContent=found?'☆ Salvar':'★ Salvo';button.setAttribute('aria-pressed',String(!found));this.announce(found?'Favorito removido.':'Tópico salvo.');},
 note(value){this.state.notes[app.currentView]=value.slice(0,20000);const saved=this.save();document.getElementById('note-status').textContent=saved?'Anotação salva neste navegador.':'Armazenamento indisponível; anotação mantida nesta sessão.';},
 markStudied(){if(!this.state.studied.includes(app.currentView))this.state.studied.push(app.currentView);this.save();document.querySelector('#tab-content').innerHTML=this.lessons(this.module());this.announce('Leitura marcada como revisada. A avaliação registra a conclusão.');},
 sourceCard(k){const s=SOURCES[k];return `<article class="source-card"><a href="${s[1]}" target="_blank" rel="noopener noreferrer">${s[0]} ↗</a><p>${s[2]}</p><small>Fonte primária · consultada em 02/10/2026 · material pode estar em inglês.</small></article>`;},
 moduleSources(m){const keys=[...new Set(AcademyContent.isNew(m)?m.lessons.flatMap(l=>l.sources||[]):m.sections.flatMap(s=>s[4]))];return `<h2>Consulte a origem das explicações</h2><p class="muted">As aulas são sínteses editoriais com exemplos próprios. Os links levam aos documentos de referência; confira versão, rede e data antes de aplicar parâmetros.</p>${keys.map(k=>this.sourceCard(k)).join('')}`;},
 sourceLibrary(){return '<p class="eyebrow">RECURSOS</p><h1>Biblioteca de fontes</h1><p class="muted">Documentos originais, guias dos protocolos e referências técnicas. Cada módulo também vincula suas aulas às fontes correspondentes.</p><div class="resource-grid">'+Object.keys(SOURCES).map(k=>this.sourceCard(k)).join('')+'</div>';},
 glossary(){return '<p class="eyebrow">RECURSOS</p><h1>Glossário de criptoeconomia</h1><p class="muted">Comece pela definição e abra o módulo para entender o contexto.</p><dl class="glossary-list panel">'+[...GLOSSARY].sort((a,b)=>a[0].localeCompare(b[0],'pt-BR')).map(([term,meaning,id])=>`<div><dt id="termo-${this.slug(term)}">${term}</dt><dd>${meaning} <button class="btn small" onclick="app.navigate('${id}')">Estudar →</button></dd></div>`).join('')+'</dl>';},
 saved(){return `<p class="eyebrow">SEU APRENDIZADO</p><h1>Favoritos e anotações</h1><p class="muted">Esses dados ficam neste navegador e podem ser perdidos se seu armazenamento for limpo.</p><button class="btn" onclick="academy.exportNotes()">Baixar minhas anotações</button><h2 style="margin-top:28px">Tópicos salvos</h2>${this.state.bookmarks.map(key=>{const r=this.resolveBookmark(key);return r?`<article class="source-card"><h3>${r.title}</h3><p>${r.m.title}</p><button class="btn small" onclick="academy.jump('${r.m.id}',${JSON.stringify(r.ref).replace(/"/g,"'")})">Abrir tópico →</button></article>`:'';}).join('')||'<p class="empty-state">Use ☆ Salvar em qualquer aula para encontrá-la aqui.</p>'}<h2 style="margin-top:28px">Suas palavras</h2>${COURSE.filter(m=>this.state.notes[m.id]).map(m=>`<article class="source-card"><h3>${m.title}</h3><p style="white-space:pre-wrap">${this.escape(this.state.notes[m.id])}</p><button class="btn small" onclick="app.navigate('${m.id}')">Editar no módulo →</button></article>`).join('')||'<p class="empty-state">Escreva no espaço de anotações ao final das aulas.</p>'}`;},
 exportNotes(){const text='# Minhas anotações — Atlas Academy\n\n'+COURSE.filter(m=>this.state.notes[m.id]).map(m=>'## '+m.title+'\n\n'+this.state.notes[m.id]).join('\n\n')+'\n\n## Favoritos\n\n'+this.state.bookmarks.map(key=>{const r=this.resolveBookmark(key);return r?'- '+r.m.title+': '+r.title:'';}).filter(Boolean).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='atlas-academy-anotacoes.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 searchResults(){const query=(this.query||'').slice(0,200),norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const plain=t=>String(t).replace(/\*\*/g,''),blockText=b=>[b.text,b.caption,b.title,b.headers&&b.headers.join(' '),b.rows&&b.rows.flat().join(' '),b.terms&&b.terms.join(' ')].filter(Boolean).join(' '),all=query?COURSE.flatMap(m=>AcademyContent.isNew(m)?m.lessons.map(l=>({m,title:l.title,ref:l.id,text:l.blocks.map(blockText).join(' '),lead:plain((l.blocks.find(b=>b.t==='p')||{text:''}).text)})):m.sections.map((s,i)=>({m,title:s[0],ref:i,text:s.slice(1,4).join(' '),lead:s[2]}))):[],hits=all.filter(h=>norm([h.m.title,h.title,h.text].join(' ')).includes(norm(query)));return `<p class="eyebrow">BUSCA NA TRILHA</p><h1>${query?'Resultados para “'+this.escape(query)+'”':'O que você quer entender?'}</h1><p class="muted">${hits.length} tópico(s) encontrado(s). </p>${hits.map(h=>`<article class="source-card"><span class="pill">${h.m.title}</span><h2 style="margin-top:14px">${h.title}</h2><p>${this.escape(h.lead.slice(0,180))}…</p><button class="btn" onclick="academy.jump('${h.m.id}',${JSON.stringify(h.ref).replace(/"/g,"'")})">Abrir aula →</button></article>`).join('')||'<p class="empty-state">Experimente “carteira”, “colateral”, “rollup” ou “staking”.</p>'}`;},
 quiz(m){return `<h2>Explique o mecanismo, depois confira</h2><p class="muted">A avaliação cobre o módulo inteiro. Responda todas as questões; cada resposta recebe uma explicação. Uma tentativa perfeita registra a conclusão.</p>${this.state.completed.includes(m.id)?'<p class="notice">✓ Você já concluiu esta avaliação. Pode refazê-la para revisar.</p>':''}<form id="academy-quiz" onsubmit="event.preventDefault();academy.checkQuiz()">${m.quiz.map((q,i)=>`<fieldset class="quiz-question"><legend>${i+1}. ${q[0]}</legend>${q[1].map((a,j)=>`<label class="quiz-answer"><input type="radio" name="academy-q${i}" value="${j}" required><span>${a}</span></label>`).join('')}<div id="feedback-${i}" class="quiz-feedback" hidden></div></fieldset>`).join('')}<button class="btn primary" type="submit">Conferir e aprender</button></form><div id="quiz-summary" class="notice" role="status" hidden></div>`;},
 checkQuiz(){const m=this.module();let score=0;const answers=m.quiz.map((q,i)=>document.querySelector('input[name="academy-q'+i+'"]:checked'));if(answers.some(a=>!a)){const res=document.getElementById('quiz-summary');res.hidden=false;res.textContent='Responda todas as questões antes de conferir.';return;}m.quiz.forEach((q,i)=>{const right=Number(answers[i].value)===q[2];if(right)score++;const feedback=document.getElementById('feedback-'+i);feedback.hidden=false;feedback.textContent=(right?'✓ Correto. ':'↻ Revise: a resposta é “'+q[1][q[2]]+'”. ')+q[3];feedback.classList.toggle('status-safe',right);});this.state.scores[m.id]=Math.max(Number(this.state.scores[m.id])||0,score);if(score===m.quiz.length&&!this.state.completed.includes(m.id))this.state.completed.push(m.id);this.save();this.updateNavigation();const res=document.getElementById('quiz-summary');res.hidden=false;res.textContent=score===m.quiz.length?'✓ '+score+'/'+m.quiz.length+' — Módulo concluído.':score+'/'+m.quiz.length+' — Leia as explicações e tente novamente.';},
 flow(m,interactive=false){return `<ol class="flow-diagram" ${interactive?'id="transaction-flow"':''}>${m.flow.map((label,i)=>`<li ${interactive&&i===this.stage?'class="active" aria-current="step"':''}><strong>PASSO ${String(i+1).padStart(2,'0')}</strong>${label}</li>`).join('')}</ol>`;},
 chart(title,labels,series,caption){
  const e=this.escape.bind(this),width=720,height=300,left=65,right=20,top=30,bottom=58;const all=series.flatMap(s=>s.values);let min=Math.min(0,...all),max=Math.max(...all);if(min===max)max=min+1;const range=max-min,maxY=max+range*.1,minY=min<0?min-range*.1:min;const x=i=>left+i*(width-left-right)/Math.max(labels.length-1,1),y=v=>top+(maxY-v)/(maxY-minY)*(height-top-bottom);const uid='plot-'+(++this.chartSerial);const colors=['#60a5fa','#67e8f9','#c4b5fd'];
  return `<figure class="panel"><h2>${title}</h2><svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="${uid}-title ${uid}-desc"><title id="${uid}-title">${e(title)}</title><desc id="${uid}-desc">${e(caption)} Valores disponíveis na tabela abaixo.</desc>${Array.from({length:5},(_,i)=>{const v=minY+(maxY-minY)*i/4;return `<line x1="${left}" x2="${width-right}" y1="${y(v)}" y2="${y(v)}" stroke="#2a3b55"/><text x="${left-10}" y="${y(v)+4}" fill="#a9b8cf" font-size="12" text-anchor="end">${e(v.toLocaleString('pt-BR',{maximumSignificantDigits:4}))}</text>`;}).join('')}${labels.map((label,i)=>`<text x="${x(i)}" y="${height-25}" fill="#a9b8cf" font-size="12" text-anchor="middle">${e(label)}</text>`).join('')}${series.map((s,j)=>`<polyline points="${s.values.map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="${colors[j%3]}" stroke-width="3"/>${s.values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="${colors[j%3]}"/>`).join('')}`).join('')}</svg><div class="chart-legend">${series.map((s,i)=>`<span style="--swatch:${colors[i%3]}">${e(s.name)}</span>`).join('')}</div><figcaption class="chart-caption">${caption}</figcaption><details><summary>Ver valores e ler o gráfico em tabela</summary><div class="table-scroll"><table class="chart-table"><thead><tr><th scope="col">Cenário</th>${series.map(s=>'<th scope="col">'+e(s.name)+'</th>').join('')}</tr></thead><tbody>${labels.map((label,i)=>'<tr><th scope="row">'+e(label)+'</th>'+series.map(s=>'<td>'+s.values[i].toLocaleString('pt-BR',{maximumSignificantDigits:6})+'</td>').join('')+'</tr>').join('')}</tbody></table></div></details></figure>`;
 },
 visuals(m){let extra='';
  if(m.id==='m1')extra=this.chart('Provas de inclusão: crescimento do caminho',[4,8,16,32,64,128].map(String),[{name:'Hashes irmãos em árvore binária completa',values:[2,3,4,5,6,7]}],'Relação matemática ilustrativa: quantidade de folhas no eixo horizontal e tamanho do caminho no vertical. Cada duplicação acrescenta um nível; não é uma medida de tempo.');
  if(m.id==='m2')extra=`<section class="panel"><h2>Árvore de Merkle: das folhas à raiz</h2><div class="merkle" role="img" aria-label="Quatro transações recebem hashes. Pares de hashes geram dois hashes intermediários, combinados em uma raiz."><div class="merkle-row"><div class="merkle-node merkle-root">Raiz = H(H12 · H34)</div></div><div class="merkle-row"><div class="merkle-node">H12 = H(H1 · H2)</div><div class="merkle-node">H34 = H(H3 · H4)</div></div><div class="merkle-row">${[1,2,3,4].map(i=>'<div class="merkle-node">H'+i+'<br>Transação '+i+'</div>').join('')}</div></div><p class="chart-caption">Para demonstrar inclusão da transação 1, combine H1 com H2 e depois H12 com H34. A raiz precisa corresponder ao compromisso confiável.</p></section>`+this.table('Papéis e garantias',['Componente','O que faz','O que não garante sozinho'],[['Carteira','Prepara e autoriza a operação','Veracidade do site ou segurança do contrato'],['Nó verificador','Valida dados e regras','Adoção econômica da rede'],['Produtor de bloco','Propõe a ordem de operações','Permissão para quebrar regras'],['Consenso','Coordena a história aceita','Verdade de dados externos'],['Oráculo','Traz dados externos','Preço correto em qualquer condição']]);
  if(m.id==='m3')extra=this.table('Carteiras: exposição e controle',['Modelo','Uso típico','Responsabilidade / limite'],[['Quente','Interações frequentes','Chaves no ambiente conectado; cuidar de permissões'],['Hardware','Assinatura isolada em dispositivo','Verificar tela, recuperação e operação autorizada'],['Fria / offline','Material de assinatura isolado','Fluxo de recuperação e movimentação mais cuidadoso'],['Custodial','Intermediário administra chaves','Dependência de solvência, acesso e retirada'],['Somente leitura','Consultar endereços','Não autoriza operações sem a chave']])+this.chart('Diluição: quantidade é diferente de preço',['Circulante','Oferta considerada'],[{name:'Milhões de tokens — exemplo',values:[10,100]}],'Cenário fictício de oferta a preço constante. Não é recomendação nem previsão. A oferta considerada na FDV pode variar entre provedores.');
  if(m.id==='m4')extra=this.chart('Contabilidade de uma transação UTXO',['Entrada','Pagamento','Troco','Taxa'],[{name:'BTC — exemplo matemático',values:[1,.3,.6999,.0001]}],'A entrada de 1 BTC equivale a pagamento + troco + taxa. A taxa é pequena nesta escala; a tabela preserva a precisão.');
  if(m.id==='m5')extra=this.chart('Gas: mais trabalho, maior custo',[21000,50000,100000,200000].map(String),[{name:'Custo em ETH a 20 gwei',values:[.00042,.001,.002,.004]}],'Hipótese de preço efetivo constante de 20 gwei. Eixo horizontal: gas usado. Não inclui todos os componentes possíveis de taxas em L2.');
  if(m.id==='m6')extra=this.comparison()+this.chart('Garantia em queda, dívida constante',['0%','−10%','−20%','−30%','−40%','−50%'],[{name:'Health factor',values:[1.6,1.44,1.28,1.12,.96,.8]},{name:'Limiar de elegibilidade',values:[1,1,1,1,1,1]}],'Exemplo: 1 ETH inicialmente a US$ 2.000, dívida de US$ 1.000, LT de 80%, sem juros. Abaixo de 1 permite liquidação no modelo Aave. Não é um parâmetro real de mercado.')+this.chart('Perda relativa em pool 50/50',['0,25×','0,5×','1×','2×','4×'],[{name:'IL em % versus manter ativos',values:[.25,.5,1,2,4].map(r=>AcademyMath.il(r)*100)}],'Produto constante, liquidez de faixa completa e sem taxas. A razão de preço está no eixo horizontal. Não aplica diretamente a pools concentrados ou outros invariantes.');
  if(m.id==='m7')extra=this.chart('Desvio da paridade: valor de 1.000 tokens',['US$ 1','US$ 0,98','US$ 0,95','US$ 0,90'],[{name:'Valor negociado em US$',values:[1000,980,950,900]}],'Cenários ilustrativos para a mesma quantidade de tokens. Preço secundário é diferente de capacidade ou direito de resgate.');
  if(m.id==='m8')extra=this.chart('Receita não é distribuição líquida',['Receita bruta','Despesas','Líquido'],[{name:'R$ por mês — cenário',values:[10000,3000,7000]}],'Valores fictícios. R$ 10 mil de receita menos R$ 3 mil de despesas resultam em R$ 7 mil antes de outras obrigações. Tokenização não garante renda.');
  if(m.id==='m9')extra=this.chart('Quanto é preciso recuperar após uma perda?',['−10%','−20%','−30%','−40%','−50%'],[{name:'Ganho necessário em %',values:[.1,.2,.3,.4,.5].map(loss=>loss/(1-loss)*100)}],'Relação matemática entre perda e recuperação, sem aportes ou custos. Uma queda de 50% exige ganho de 100% sobre o saldo restante.');
  if(m.id==='m10')extra=this.chart('O valor líquido depende de todas as etapas',['Inicial','Compra / câmbio','Rede','Saída'],[{name:'US$ restantes — cenário ilustrativo',values:[1000,995,993.5,985.5]}],'Exemplo inventado de custos cumulativos. Não é cotação de remessa. Compare disponibilidade, moeda final, spread, taxas e resgate.');
  if(m.id==='m2')extra+=this.chart('Mais demanda que capacidade: a fila cresce',['1','2','3','4','5'],[{name:'Operações pendentes ao final',values:AcademyMath.backlog(100,60,5)}],'Cenário fictício: chegam 100 operações por intervalo, cabem 60 no bloco e a fila começa vazia. Não modela prioridade por taxa, descarte nem confirmação. Experimente parâmetros na aba Laboratórios.');
  if(m.id==='m6')extra+=this.table('De onde vem o rendimento?',['Atividade','Fonte econômica','Dependências relevantes'],[['Lending','Juros de tomadores e eventuais incentivos','Garantias, liquidez, taxas, oráculos e contrato'],['Staking PoS','Recompensas e taxas segundo o consenso','Validador, disponibilidade, penalidades e saída'],['Staking líquido','Exposição às recompensas de staking por uma representação','Operador, contrato, mercado do token e resgate'],['Liquidez AMM','Taxas de trocas e eventuais incentivos','Volume, composição, faixa e perda relativa'],['Farming','Incentivos e reinvestimento de estratégias','Emissão, preço de recompensa e camadas de contratos']]);
  return `<section class="panel"><p class="eyebrow">MAPA DO MECANISMO</p><h2>${m.title}: conecte as etapas</h2>${this.flow(m)}<p class="chart-caption">Leia na ordem numerada. Cada etapa tem uma função e pode introduzir dependências próprias.</p></section>${extra}`;
 },
 table(title,headers,rows){return `<section class="panel"><h2>${title}</h2><div class="table-scroll"><table class="chart-table comparison"><thead><tr>${headers.map(h=>'<th scope="col">'+h+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map((c,i)=>i===0?'<th scope="row">'+c+'</th>':'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table></div></section>`;},
 comparison(){return this.table('Empréstimos: compare a versão e o mercado',['Critério','Aave V3','Compound III (Comet)'],[['Ativo emprestado','Múltiplas reservas elegíveis, sujeitas a modos e limites','Um ativo base por mercado'],['Garantia','Reservas elegíveis; habilitação e restrições podem se aplicar','Colaterais aceitos pelo mercado'],['Juros de fornecimento','Reservas fornecidas conforme regras; garantia depende da elegibilidade','Saldo positivo do ativo base; colateral não recebe esses juros'],['Limite de tomada','LTV e configurações do mercado','Borrow collateral factors e limites'],['Liquidação','HF e regras de liquidate do mercado','Fatores de liquidação, absorb e venda de colateral'],['Lembrete','Não aplicar parâmetros de outra rede automaticamente','Não confundir com Compound v2']])+`<p class="notice">Referências: <a href="${SOURCES.aave[1]}" target="_blank" rel="noopener">Aave V3</a>, <a href="${SOURCES.compound[1]}" target="_blank" rel="noopener">Compound III</a> e <a href="${SOURCES.comet[1]}" target="_blank" rel="noopener">especificação Comet</a>.</p>`;},
 field(id,label,value,min,max,step=1){return `<label class="sim-field" for="${id}">${label}<input id="${id}" type="number" value="${value}" min="${min}" ${max!==null?'max="'+max+'"':''} step="${step}"></label>`;},
 extraLabs(m){
  if(m.id==='m1')return `<section class="panel"><h2>Hash real: SHA-256</h2><p class="muted">Compare duas mensagens. O resultado tem 256 bits, representados por 64 caracteres hexadecimais.</p><label class="sim-field" for="sha-message">Mensagem pública de teste<input id="sha-message" value="Alice envia 1 ETH"></label><button class="btn primary" style="margin:18px 0" onclick="academy.sha()">Calcular SHA-256</button><output id="sha-result" class="hash-output" aria-live="polite">Digite uma mensagem e calcule.</output><p class="chart-caption">Nunca cole chaves, frases de recuperação ou dados sensíveis. O cálculo usa Web Crypto localmente.</p></section>`;
  if(m.id==='m2')return `<section class="panel"><h2>Uma transação, do início à finalidade</h2><p class="muted">Avance uma etapa por vez e explique quem age e qual garantia surge.</p>${this.flow(m,true)}<div id="stage-explanation" class="step-explanation" aria-live="polite"></div><div class="actions" style="margin-top:18px"><button class="btn" onclick="academy.transactionStep(-1)">← Voltar etapa</button><button class="btn primary" onclick="academy.transactionStep(1)">Avançar etapa →</button><button class="btn" onclick="academy.transactionStep(0,true)">Recomeçar</button></div><p class="notice">Modelo conceitual. Consenso, finalidade e processamento de transações variam entre redes; o fluxo não envia uma operação real.</p></section>`;
  if(m.id==='m6')return `<section class="panel" id="lending-simulator"><p class="eyebrow">MODELO AAVE · CENÁRIOS DIDÁTICOS</p><h2>Garantia, dívida e margem de liquidação</h2><p class="muted">Altere preço da garantia e da dívida separadamente. Juros simples aproximam a evolução da dívida; todos os parâmetros abaixo são editáveis e fictícios.</p><div class="sim-grid">${this.field('sim-qty','Quantidade de garantia',1,.001,null,.1)}${this.field('sim-price','Preço da garantia (US$)',2000,.01,null,10)}${this.field('sim-debt','Quantidade do ativo emprestado',1000,0,null,10)}${this.field('sim-debt-price','Preço do ativo da dívida (US$)',1,.001,null,.01)}${this.field('sim-apr','Juros anuais da dívida (%)',8,0,1000,.1)}${this.field('sim-days','Dias decorridos',0,0,36500,1)}${this.field('sim-lt','Limiar de liquidação · LT (%)',80,.1,100,.1)}${this.field('sim-ltv','Limite inicial de tomada · LTV (%)',70,.1,100,.1)}</div><div id="lending-error" role="alert" class="notice warning" hidden></div><div id="lending-metrics" class="metrics" aria-live="polite"></div><p id="lending-status" class="notice"></p><div id="lending-chart"></div><div class="actions"><button class="btn" onclick="academy.lendingPreset('base')">Exemplo inicial</button><button class="btn" onclick="academy.lendingPreset('drop')">Garantia cai 40%</button><button class="btn" onclick="academy.lendingPreset('debt')">Ativo da dívida sobe 50%</button><button class="btn" onclick="academy.lendingPreset('combined')">Choques combinados</button></div></section><section class="panel" id="amm-simulator"><h2>AMM: uma compra muda as reservas</h2><p class="muted">Produto constante, compra de ETH com um token de preço fictício US$ 1 e taxa editável. Não simula liquidez concentrada.</p><div class="sim-grid">${this.field('amm-x','Reserva do token usado para pagar',20000,.01,null,100)}${this.field('amm-y','Reserva de ETH',10,.001,null,.1)}${this.field('amm-input','Token usado na troca',1000,0,null,100)}${this.field('amm-fee','Taxa da troca (%)',.3,0,99.9,.1)}</div><div id="amm-result" class="notice" aria-live="polite"></div></section>`;
  return `<section class="panel"><h2>Da aula ao experimento</h2><p class="muted">${m.id==='m3'?'Explore a oferta, a distribuição e a diluição de um token.':m.id==='m4'?'Consuma UTXOs e observe como surgem novas saídas e troco.':m.id==='m5'?'Explore o cofre, o custo de gas e a diferença entre autorizar e executar.':m.id==='m7'?'Teste cenários de lastro e pressão de venda sem confundir hipótese com previsão.':m.id==='m8'?'Distribua participações e acompanhe o fluxo hipotético de renda.':m.id==='m9'?'Mude alocação e leia as curvas como resultados de um modelo, não previsões.':'Compare trajetos de pagamento e explique todas as etapas de custo.'}</p><p>Abra os laboratórios originais abaixo. Depois registre, nas suas palavras, o que mudou, por que mudou e quais premissas o experimento simplificou.</p></section>`;
 },
 initExtraLabs(){if(app.currentView==='m2'){this.transactionStep(0);if(!document.getElementById('queue-simulator'))document.querySelector('#tab-labs .panel').insertAdjacentHTML('afterend',`<section id="queue-simulator" class="panel"><h2>Demanda, capacidade e fila</h2><p class="muted">Mude quantas operações chegam e quantas cabem por intervalo. Cada operação usa uma unidade neste modelo simples.</p><div class="sim-grid">${this.field('queue-arrivals','Chegadas por intervalo',100,0,100000,1)}${this.field('queue-capacity','Capacidade por intervalo',60,0,100000,1)}${this.field('queue-blocks','Intervalos observados',5,1,30,1)}</div><div id="queue-result" style="margin-top:24px" aria-live="polite"></div></section>`);document.querySelectorAll('#queue-simulator input').forEach(el=>el.oninput=()=>this.queueCalc());this.queueCalc();}if(app.currentView==='m6'){document.querySelectorAll('#lending-simulator input').forEach(el=>el.oninput=()=>this.lendingCalc());document.querySelectorAll('#amm-simulator input').forEach(el=>el.oninput=()=>this.ammCalc());this.lendingCalc();this.ammCalc();}},
 queueCalc(){const out=document.getElementById('queue-result');try{const a=Number(document.getElementById('queue-arrivals').value),c=Number(document.getElementById('queue-capacity').value),n=Number(document.getElementById('queue-blocks').value);if(a>100000||c>100000)throw new RangeError('Use até 100 mil operações por intervalo.');const pending=AcademyMath.backlog(a,c,n);out.innerHTML=this.chart('Fila ao final de cada intervalo',pending.map((_,i)=>String(i+1)),[{name:'Operações ainda pendentes',values:pending}],'Hipótese: chegadas constantes, capacidade constante e fila inicial vazia. Não representa tempo de finalidade, prioridades, transações inválidas ou taxas reais.');}catch(e){out.innerHTML='<p class="notice warning">'+this.escape(e.message)+'</p>'; }},
 initOriginalLabs(id){if(id==='m1')m1lab.bind();if(id==='m2')chainLab.init();if(id==='m3')tokenLab.calc();if(id==='m4')btcLab.init();if(id==='m5'){web5.init();gasLab.calc();buildLab.update();}if(id==='m6'){poolLab.create();ilLab.calc();lendLab.calc();aprLab.calc();}if(id==='m7'){vaultLab.calc();depegLab.reset();stableCmp.render();}if(id==='m8')rwaLab.init();if(id==='m9')portLab.init();if(id==='m10')sendLab.calc();},
 refreshVisuals(){},
 async sha(){const out=document.getElementById('sha-result');if(!window.crypto?.subtle){out.textContent='Web Crypto indisponível neste ambiente. Consulte o laboratório didático e a fonte NIST.';return;}const input=document.getElementById('sha-message').value;const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(input));out.textContent=Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');},
 transactionStep(delta,reset=false){this.stage=reset?0:Math.min(5,Math.max(0,this.stage+delta));const explanations=['A carteira monta rede, destinatário, valor e parâmetros. O usuário verifica e assina. A chave privada não deve ser transmitida.','Um nó recebe a operação e verifica condições antes de propagá-la. Serviços RPC são interfaces de acesso à rede.','A transação pode ficar pendente e disputar inclusão. Prioridade e mempools variam. Enviar não significa incluir.','Um produtor escolhe operações e propõe um bloco. A ordem pode afetar preços, arbitragem e liquidações.','Outros nós verificam regras e execução. Uma proposta inválida pode ser rejeitada. Validação não depende de confiar no site.','A operação alcança confirmação e, conforme o consenso, finalidade. Mais segurança exige as hipóteses específicas da rede.'];document.getElementById('transaction-flow').outerHTML=this.flow(this.module('m2'),true);document.getElementById('stage-explanation').textContent=explanations[this.stage];},
 lendingValues(){return {quantity:Number(document.getElementById('sim-qty').value),price:Number(document.getElementById('sim-price').value),debtUnits:Number(document.getElementById('sim-debt').value),debtPrice:Number(document.getElementById('sim-debt-price').value),apr:Number(document.getElementById('sim-apr').value),days:Number(document.getElementById('sim-days').value),lt:Number(document.getElementById('sim-lt').value)};},
 lendingCalc(){const err=document.getElementById('lending-error');try{const p=this.lendingValues(),ltv=Number(document.getElementById('sim-ltv').value);if(!Number.isFinite(ltv)||ltv<=0||ltv>p.lt)throw new RangeError('LTV inicial deve ser positivo e não superar o limiar de liquidação.');const r=AcademyMath.lending(p);if(p.apr>1000||p.days>36500)throw new RangeError('Use juros até 1.000% e prazo até 36.500 dias.');err.hidden=true;const usd=v=>'US$ '+v.toLocaleString('pt-BR',{maximumFractionDigits:2});document.getElementById('lending-metrics').innerHTML=[['Garantia atual',usd(r.collateral)],['Dívida atual',usd(r.debt)],['Health factor',r.hf===Infinity?'∞ · sem dívida':r.hf.toFixed(3)],['LTV atual',(r.ltv*100).toFixed(2)+'%'],['Preço-limite da garantia',r.debt?usd(r.liquidationPrice):'Sem limite por dívida'],['Limite inicial de tomada',usd(r.collateral*ltv/100)]].map(([label,value])=>`<div class="metric"><small>${label}</small><strong>${value}</strong></div>`).join('');const status=document.getElementById('lending-status');status.className='notice '+(r.hf<1?'status-danger':r.hf<1.5?'status-risk':'status-safe');status.textContent=r.hf===Infinity?'Sem dívida: não há elegibilidade por insuficiência de garantia neste modelo.':r.hf<1?'HF abaixo de 1: posição elegível para liquidação no modelo Aave. Este simulador não executa a operação nem prevê penalidade.':r.hf===1?'HF exatamente no limiar. Sem margem para queda da garantia, alta da dívida ou juros.':'HF acima de 1. A margem pode diminuir; esse número não representa segurança contra falhas de contrato, oráculo ou mercado.';if(r.debt){const ratios=[.4,.6,.8,1,1.2,1.4];document.getElementById('lending-chart').innerHTML=this.chart('Sensibilidade ao preço da garantia',ratios.map(x=>Math.round(x*100)+'%'),[{name:'Health factor',values:ratios.map(x=>r.hf*x)},{name:'Limiar',values:ratios.map(()=>1)}],'100% é o preço atual informado. Dívida e juros ficam constantes nesta curva. Abaixo de 1 permite liquidação; a tabela oferece os valores.');}else document.getElementById('lending-chart').innerHTML='<p class="notice">Sem dívida, HF é infinito. Adicione dívida para visualizar a curva.</p>';}
  catch(e){err.hidden=false;err.textContent=e.message;document.getElementById('lending-metrics').innerHTML='';document.getElementById('lending-chart').innerHTML='';document.getElementById('lending-status').textContent='Corrija os parâmetros para calcular.';}},
 lendingPreset(name){const presets={base:[1,2000,1000,1,8,0,80,70],drop:[1,1200,1000,1,8,0,80,70],debt:[1,2000,1000,1.5,8,0,80,70],combined:[1,1400,1000,1.2,15,180,80,70]};['qty','price','debt','debt-price','apr','days','lt','ltv'].forEach((id,i)=>document.getElementById('sim-'+id).value=presets[name][i]);this.lendingCalc();},
 ammCalc(){const out=document.getElementById('amm-result');try{const x=Number(document.getElementById('amm-x').value),y=Number(document.getElementById('amm-y').value),input=Number(document.getElementById('amm-input').value),fee=Number(document.getElementById('amm-fee').value)/100;const r=AcademyMath.amm(x,y,input,fee);out.textContent=`Saída: ${r.output.toLocaleString('pt-BR',{maximumFractionDigits:6})} ETH. Razão de reservas antes: ${(x/y).toFixed(2)} por ETH; depois: ${(r.newX/r.newY).toFixed(2)}. Entrada líquida para precificação: ${(input*(1-fee)).toFixed(2)}. A taxa permanece na reserva neste modelo.`;out.classList.remove('warning');}catch(e){out.textContent=e.message;out.classList.add('warning');}},
 fixLabLabels(){document.querySelectorAll('.legacy-content input,.legacy-content select').forEach((el,i)=>{if(el.type==='hidden'||el.type==='radio'||el.type==='checkbox')return;if(!el.id)el.id='legacy-field-'+i;const label=el.closest('label')||document.querySelector('label[for="'+el.id+'"]');if(label)return;const near=el.parentElement.querySelector('label')||el.previousElementSibling;el.setAttribute('aria-label',(near?.textContent||el.placeholder||'Parâmetro do laboratório '+(i+1)).trim().slice(0,120));});document.querySelectorAll('.legacy-content canvas').forEach(c=>{c.setAttribute('role','img');c.setAttribute('aria-label','Gráfico didático do laboratório. Consulte os resultados numéricos e os gráficos com tabelas na aba Diagramas e gráficos.');});},
 bindLabSafety(){document.querySelector('.legacy-labs')?.addEventListener('toggle',e=>{if(e.target.open){if(app.currentView==='m3'){tokenLab.ensureCharts();tokenLab.calc();}if(app.currentView==='m6'){defiCharts.ensure();poolLab.renderChart();ilLab.calc();}if(app.currentView==='m7'){stableCharts.ensure();depegLab.redraw();}if(app.currentView==='m9'){portLab.ensureCharts();portLab.update();}Object.values(window.Chart?.instances||{}).forEach(c=>c.resize());this.fixLabLabels();}});}
};
document.addEventListener('DOMContentLoaded',()=>academy.init());
